-- SQLx runs this file in one transaction, so CONCURRENTLY is not possible.
-- lock_timeout makes a busy table fail the migrate step instead of queueing
-- the queries of the running release. Keep api_keys last: the request path
-- reads it. Do not edit this file after release: SQLx checks its hash.
SET LOCAL lock_timeout = '5s';
DROP INDEX IF EXISTS idx_fingrid_actuals_dataset_start;
DROP INDEX IF EXISTS idx_fingrid_forecasts_issued;
DROP INDEX IF EXISTS idx_api_keys_user_id;
